create or replace function public.request_account_erasure() returns uuid language plpgsql security definer set search_path = 'public', 'pg_catalog' as $$ declare v_request_id uuid; v_memberships integer; begin if auth.uid() is null then raise exception 'Not authenticated'; end if; select count(*) into v_memberships from public.user_roles where user_id = auth.uid(); insert into public.account_erasure_requests (user_id, status, metadata) values (auth.uid(), case when v_memberships = 0 then 'PENDING' else 'BLOCKED' end, jsonb_build_object('organization_memberships', v_memberships, 'requires_membership_transfer', v_memberships > 0)) returning id into v_request_id; return v_request_id; end; $$;